.liquid-wrap {
  position: relative; width: 100%; height: 100%;
  display: flex; align-items: center; justify-content: center; overflow: hidden;
}
.liquid-bg {
  width: 150%; height: 150%; position: absolute;
  background: linear-gradient(45deg, #ff9a9e, #fecfef, #a1c4fd, #c2e9fb);
  background-size: 400% 400%; animation: gradFlow 5s ease infinite; z-index: 0;
}
.glass-card-light {
  width: 220px; height: 280px; background: rgba(255, 255, 255, 0.3);
  backdrop-filter: blur(15px); border: 2px solid rgba(255, 255, 255, 0.6);
  border-radius: 20px; z-index: 10; display: flex; flex-direction: column;
  align-items: center; justify-content: center; box-shadow: 0 20px 40px rgba(0,0,0,0.1);
  color: #333; font-family: sans-serif;
}
@keyframes gradFlow { 0% { background-position: 0% 50%; } 50% { background-position: 100% 50%; } 100% { background-position: 0% 50%; } }
